import { describe, expect, it } from 'vitest';
import { importSong } from '../../src/core/import';
import { extractPdfText } from '../../src/core/pdf';
import { loadFixtureBuffer } from '../helpers/fixtures';

/**
 * Hard PDF inputs generated by `node scripts/make-pdf-fixtures.mjs`.
 * Goal: extraction is best effort, but it must never crash and must fail
 * cleanly on encrypted or corrupted files.
 */

const extract = (name: string) => extractPdfText(loadFixtureBuffer(`generated/${name}`));
const squeeze = (text: string) => text.replace(/\s+/g, ' ').trim();

describe('PDF torture fixtures', () => {
  it('reads a multi-page two-column songbook in order', async () => {
    const extracted = await extract('generated-multipage-columns.pdf');
    expect(extracted.pages).toBe(3);
    expect(extracted.hasText).toBe(true);

    const text = squeeze(extracted.text);
    expect(text.indexOf('number 1 here')).toBeLessThan(text.indexOf('number 36 here'));

    const result = importSong(extracted.text);
    expect(result.stats.merged).toBeGreaterThanOrEqual(60);
    expect(result.chordpro).not.toMatch(/^Page\s+\d+\s*\/\s*\d+$/m);
  });

  it('extracts rotated text without crashing', async () => {
    const extracted = await extract('generated-rotated.pdf');
    expect(extracted.pages).toBe(1);
    expect(extracted.hasText).toBe(true);
    expect(() => importSong(extracted.text)).not.toThrow();
  });

  it('keeps the text side of a mixed text/image PDF', async () => {
    const extracted = await extract('generated-mixed.pdf');
    expect(extracted.pages).toBe(1);
    expect(extracted.hasText).toBe(true);
    expect(squeeze(extracted.text)).toContain('Mixed Content');
    expect(squeeze(extracted.text)).toContain('After the image');

    const result = importSong(extracted.text);
    expect(result.stats.merged).toBeGreaterThanOrEqual(1);
  });

  it('removes soft hyphens from a hyphenated page', async () => {
    const extracted = await extract('generated-hyphenated.pdf');
    expect(extracted.hasText).toBe(true);
    expect(squeeze(extracted.text)).toContain('extraordinarily complicated demonstration');

    const result = importSong(extracted.text);
    expect(result.stats.merged).toBeGreaterThanOrEqual(1);
  });

  it('rejects an encrypted PDF with a password error', async () => {
    await expect(extract('generated-encrypted.pdf')).rejects.toThrow(/password/i);
  });

  it('rejects corrupted and empty PDFs', async () => {
    const valid = Buffer.from(loadFixtureBuffer('generated/generated-single-column.pdf'));
    await expect(extractPdfText(new Uint8Array(valid.subarray(0, 400)))).rejects.toThrow();
    await expect(extractPdfText(new Uint8Array(0))).rejects.toThrow();
  });

  it('keeps the single-page two-column reading order from the old fixture', async () => {
    const extracted = await extract('generated-two-columns.pdf');
    const text = squeeze(extracted.text);
    expect(text.indexOf('number 1 here')).toBeLessThan(text.indexOf('number 8 here'));
  });
});
